// Set time range for calendar check
const now = new Date();
const tomorrow = new Date(now);
tomorrow.setDate(tomorrow.getDate() + 1);
const nextWeek = new Date(now);
nextWeek.setDate(nextWeek.getDate() + 7);

return {
  json: {
    timeMin: now.toISOString(),
    timeMax: nextWeek.toISOString(),
    calendarId: 'primary',
    teamMembers: [
      {
        name: 'Partner 1',
        email: 'partner1@vcfirm.com',
        calendarId: 'partner1@vcfirm.com'
      },
      {
        name: 'Partner 2',
        email: 'partner2@vcfirm.com',
        calendarId: 'partner2@vcfirm.com'
      },
      {
        name: 'Associate 1',
        email: 'associate1@vcfirm.com',
        calendarId: 'associate1@vcfirm.com'
      }
    ]
  }
};

// Process calendar data and meeting requests to find available slots
const teamMembers = $input.first().json.teamMembers;
const pendingRequests = $input.last().json;
const calendarEvents = $input.first().json;

// Create a map of busy times for each team member
const busyTimes = {};
teamMembers.forEach(member => {
  busyTimes[member.email] = [];
});

// Add existing events to busy times
if (Array.isArray(calendarEvents.items)) {
  calendarEvents.items.forEach(event => {
    if (event.start && event.end) {
      const start = new Date(event.start.dateTime || `${event.start.date}T00:00:00`);
      const end = new Date(event.end.dateTime || `${event.end.date}T23:59:59`);

      const calendarId = event.organizer && event.organizer.email;
      if (calendarId && busyTimes[calendarId]) {
        busyTimes[calendarId].push({ start, end });
      }
    }
  });
}

// Process each pending meeting request
const processedRequests = [];

if (Array.isArray(pendingRequests)) {
  pendingRequests.forEach(request => {
    // Determine which team members should attend based on request details
    let assignedMembers = [];

    // Simple assignment logic based on meeting type
    if (request.meetingType === 'Initial Screening') {
      assignedMembers = [teamMembers[2]]; // Associate
    } else if (request.meetingType === 'Pitch Meeting') {
      assignedMembers = [teamMembers[0], teamMembers[2]]; // Partner 1 and Associate
    } else if (request.meetingType === 'Due Diligence') {
      assignedMembers = [teamMembers[0], teamMembers[1], teamMembers[2]]; // All team members
    } else {
      assignedMembers = [teamMembers[0]]; // Default to Partner 1
    }

    // Find available time slots
    const availableSlots = findAvailableTimeSlots(busyTimes, assignedMembers, request);

    // Add processed request to output
    processedRequests.push({
      ...request,
      assignedMembers: assignedMembers.map(m => m.email).join(','),
      availableSlots: availableSlots,
      suggestedSlot: availableSlots.length > 0 ? availableSlots[0] : null,
      status: availableSlots.length > 0 ? 'Ready for Scheduling' : 'No Availability'
    });
  });
}

// Helper function to find available time slots
function findAvailableTimeSlots(busyTimes, teamMembers, request) {
  const availableSlots = [];
  const requestDate = new Date(request.preferredDate || Date.now());
  const startHour = 9; // 9 AM
  const endHour = 17; // 5 PM
  const meetingDuration = parseInt(request.duration) || 60; // in minutes

  // Check the next 5 business days
  for (let dayOffset = 0; dayOffset < 5; dayOffset++) {
    const currentDate = new Date(requestDate);
    currentDate.setDate(requestDate.getDate() + dayOffset);

    // Skip weekends
    if (currentDate.getDay() === 0 || currentDate.getDay() === 6) {
      continue;
    }

    // Check each 30-minute slot during business hours
    for (let hour = startHour; hour < endHour; hour++) {
      for (let minute = 0; minute < 60; minute += 30) {
        if (hour === endHour - 1 && minute + meetingDuration > 60) {
          continue; // Skip if meeting would extend past end of day
        }

        const slotStart = new Date(currentDate);
        slotStart.setHours(hour, minute, 0, 0);

        const slotEnd = new Date(slotStart);
        slotEnd.setMinutes(slotStart.getMinutes() + meetingDuration);

        // Check if all team members are available during this slot
        let allAvailable = true;
        for (const member of teamMembers) {
          if (!isTimeSlotAvailable(busyTimes[member.email], slotStart, slotEnd)) {
            allAvailable = false;
            break;
          }
        }

        if (allAvailable) {
          availableSlots.push({
            start: slotStart.toISOString(),
            end: slotEnd.toISOString(),
            date: slotStart.toDateString(),
            time: slotStart.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})
          });
        }
      }
    }
  }

  return availableSlots;
}

// Helper function to check if a time slot conflicts with busy times
function isTimeSlotAvailable(busyTimes, start, end) {
  for (const busy of busyTimes) {
    if (start < busy.end && end > busy.start) {
      return false; // Conflict found
    }
  }
  return true; // No conflicts
}

return { json: { processedRequests } };

