// Set time range for today's meetings
const now = new Date();
const startOfDay = new Date(now);
startOfDay.setHours(0, 0, 0, 0);
const endOfDay = new Date(now);
endOfDay.setHours(23, 59, 59, 999);

return {
  json: {
    timeMin: startOfDay.toISOString(),
    timeMax: endOfDay.toISOString(),
    calendarId: 'primary',
    teamMembers: [
      {
        name: 'Partner 1',
        email: 'partner1@vcfirm.com',
        calendarId: 'partner1@vcfirm.com'
      },
      {
        name: 'Partner 2',
        email: 'partner2@vcfirm.com',
        calendarId: 'partner2@vcfirm.com'
      },
      {
        name: 'Associate 1',
        email: 'associate1@vcfirm.com',
        calendarId: 'associate1@vcfirm.com'
      }
    ]
  }
};

// Process today's meetings to send reminders
const meetings = $input.item.json.items || [];
const todaysMeetings = [];

// Filter for external meetings (with non-company attendees)
for (const meeting of meetings) {
  if (meeting.attendees && meeting.attendees.length > 0) {
    const externalAttendees = meeting.attendees.filter(attendee => {
      return !attendee.email.endsWith('@vcfirm.com');
    });

    if (externalAttendees.length > 0) {
      const startTime = new Date(meeting.start.dateTime || `${meeting.start.date}T00:00:00`);
      const endTime = new Date(meeting.end.dateTime || `${meeting.end.date}T23:59:59`);

      todaysMeetings.push({
        id: meeting.id,
        summary: meeting.summary,
        description: meeting.description,
        startTime: startTime.toISOString(),
        endTime: endTime.toISOString(),
        formattedStartTime: startTime.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}),
        location: meeting.location || 'Virtual Meeting',
        hangoutLink: meeting.hangoutLink || '',
        organizer: meeting.organizer ? meeting.organizer.email : '',
        attendees: meeting.attendees.map(a => a.email).join(', ')
      });
    }
  }
}

// Sort meetings by start time
todaysMeetings.sort((a, b) => new Date(a.startTime) - new Date(b.startTime));

return { json: { todaysMeetings } };

